// Public, already-observed Claude Code state; only a live Codexio receiver gets it.
const config = __CODEXIO_CONFIG__;
let timer = null;
let sending = false;
let pending = null;
let last = null;
const contexts = new Map();
// Bind the engine's prompt row UUID to its main turn, without reading text or
// assuming that a turn ID and a transcript prompt ID are interchangeable.
const sessions = new Map();
async function sessionState($) {
  try {
    const id = await $.session.id();
    if (!sessions.has(id)) {
      sessions.set(id,{turn:null,prompts:[]});
      while (sessions.size > 32) sessions.delete(sessions.keys().next().value);
    }
    return sessions.get(id);
  } catch {return {turn:null,prompts:[]};}
}
function stepFields(e) {
  const fields = {};
  if (typeof e.model === 'string' && e.model) fields.model = e.model;
  if (typeof e.effort === 'string' || typeof e.effort === 'number') fields.reasoning_effort = String(e.effort);
  return fields;
}
async function runtimeState($) {
  if (!(await $.fs.exists(config.runtime))) return null;
  const runtime = JSON.parse(await $.fs.read(config.runtime));
  return runtime.url && runtime.nonce && runtime.url.startsWith('http://127.0.0.1:') ? runtime : null;
}
async function deliver($, usage, scheduled = false, contextId = '', fields = {}) {
