    const runtime = await runtimeState($);
    if (!runtime) return false;
    const now = await $.clock.now();
    const session = await $.session.id();
    const surfaces = await $.session.surfaces();
    const surface = surfaces.includes('desktop') ? 'desktop' : 'cli';
    const window = usage?.context?.window;
    if (contextId) {
      const key = session + ':' + contextId, prior = contexts.get(key);
      const point = {...prior,session_id:session,message_uuid:contextId,...fields};
      if (typeof window === 'number' && Number.isSafeInteger(window) && window > 0) point.window = window;
      if (point.window || point.model || point.reasoning_effort) {
        if (!prior || ['window','model','reasoning_effort'].some(k => prior[k] !== point[k])) {
          point.observed_at = now/1000;
          contexts.set(key,point);
