      }
      while (contexts.size > 32) contexts.delete(contexts.keys().next().value);
    }
    const windows = (usage?.rateLimits ?? []).filter(w => ['five_hour','seven_day'].includes(w.kind))
      .filter(w => typeof w.percentUsed === 'number' && Number.isFinite(w.percentUsed) && w.percentUsed >= 0 && w.percentUsed <= 100)
      .map(w => ({kind:w.kind,percentUsed:w.percentUsed,resetsAt:typeof w.resetsAt === 'string' ? w.resetsAt : null}));
