    const signature = JSON.stringify([session,windows,points,runtime.nonce]);
    if (!scheduled && last && last.signature === signature && now >= last.time && now-last.time < 60000) return true;
    scheduled = scheduled || Boolean(pending?.payload?.scheduled && now-pending.time <= 5000);
