}
async function readCurrent($, scheduled = false, contextId = '', fields = {}) {
  try {
    if (!(await runtimeState($))) return false;
    return await deliver($,await $.session.usage(),scheduled,contextId,fields);
  } catch {return false;}
}
async function schedule($) {
  if (timer) return;
  try {
    if (!(await runtimeState($))) return;
    const now = await $.clock.now();
    // Read live engine state on minute boundaries, without model/API requests.
    timer = $.clock.after(Math.max(1,60000-now%60000),() => {void pulse($);});
  } catch {}
}
async function pulse($) {
