  if (await readCurrent($,true)) await schedule($);
}
export const register = on => {
  on('session.start',async ($,e,next) => {await readCurrent($);await schedule($);return next(e);});
  on('session.measure',async ($,e,next) => {await deliver($,e);await schedule($);return next(e);});
